// Game board size
#define BOARD_WIDTH 800
#define BOARD_HEIGHT 600

// Snake and food image sizes
#define IMAGE_SIZE 32

// Game states
enum GameState {
    GameStateRunning,
    GameStateGameOver,
};

// Snake segment struct
typedef struct SnakeSegment {
    int x;
    int y;
    int prev_x;
    int prev_y;
} SnakeSegment;

// Game state struct
typedef struct Game {
    SDL_Window *window;
    SDL_Renderer *renderer;
    SDL_Surface *background_surface;
    SDL_Texture *background_texture;
    SDL_Surface *snake_head_surface;
    SDL_Texture *snake_head_texture;
    SDL_Surface *snake_body_surface;
    SDL_Texture *snake_body_texture;
    SDL_Surface *food_surface;
    SDL_Texture *food_texture;
    SnakeSegment *snake;
    int snake_length;
    int score;
    int food_x;
    int food_y;
    int game_state;
    int frame_rate;
    Uint32 start_ticks;
} Game;

// Function prototypes
void InitGame(Game *game);
void LoadImages(Game *game);
void UpdateGame(Game *game);
void RenderGame(Game *game);
void HandleInput(Game *game);
void FreeGame(Game *game);

int main(int argc, char *argv[]) {
    Game game;

    // Initialize the game
    InitGame(&game);

    // Load images
    LoadImages(&game);

    // Game loop
    while (game.game_state == GameStateRunning) {
        // Handle input
        HandleInput(&game);

        // Update game logic
        UpdateGame(&game);

        // Render the game
        RenderGame(&game);

        // Limit the frame rate
        SDL_Delay((1000 / game.frame_rate) - (SDL_GetTicks() - game.start_ticks));
        game.start_ticks = SDL_GetTicks();
    }

    // Game over
    if (game.game_state == GameStateGameOver) {
        printf("Game over!\n");
    }

    // Free resources
    FreeGame(&game);

    return 0;
}

void InitGame(Game *game) {
    // Initialize SDL
    SDL_Init(SDL_INIT_VIDEO);

    // Create window
    game->window = SDL_CreateWindow("Snake",
                                     SDL_WINDOWPOS_CENTERED,
                                     SDL_WINDOWPOS_CENTERED,
                                     BOARD_WIDTH,
                                     BOARD_HEIGHT,
                                     SDL_WINDOW_SHOWN);

    // Create renderer
    game->renderer = SDL_CreateRenderer(game->window, -1, SDL_RENDERER_ACCELERATED);

    // Set up background
    game->background_surface = SDL_LoadBMP("background.bmp");
    game->background_texture = SDL_CreateTextureFromSurface(game->renderer, game->background_surface);
    SDL_FreeSurface(game->background_surface);

    // Set up snake images
    game->snake_head_surface = SDL_LoadBMP("snake_head.bmp");
    game->snake_head_texture = SDL_CreateTextureFromSurface(game->renderer, game->snake_head_surface);
