void RenderGame(Game *game) {
    SDL_Rect rect;

    // Clear the screen
    SDL_SetRenderDrawColor(game->renderer, 0x00, 0x00, 0x00, SDL_ALPHA_OPAQUE);
    SDL_RenderClear(game->renderer);

    // Draw background
    rect.x = 0;
    rect.y = 0;
    rect.w = BOARD_WIDTH;
    rect.h = BOARD_HEIGHT;
    SDL_RenderCopy(game->renderer, game->background_texture, NULL, &rect);

    // Draw snake
    for (int I = 0; I < game->snake_length; ++i) {
        rect.x = game->snake[i].x * IMAGE_SIZE;
        rect.y = game->snake[i].y * IMAGE_SIZE;
        rect.w = IMAGE_SIZE;
        rect.h = IMAGE_SIZE;

        if (i == 0) {
            SDL_RenderCopy(game->renderer, game->snake_head_texture, NULL, &rect);
        } else {
            SDL_RenderCopy(game->renderer, game->snake_body_texture, NULL, &rect);
        }

        // Draw interpolation line between previous and current position
        SDL_SetRenderDrawColor(game->renderer, 0xFF, 0x00, 0x00, SDL_ALPHA_OPAQUE);
        SDL_RenderDrawLine(game->renderer, game->snake[i].prev_x * IMAGE_SIZE + IMAGE_SIZE / 2,
                            game->snake[i].prev_y * IMAGE_SIZE + IMAGE_SIZE / 2,
                            game->snake[i].x * IMAGE_SIZE + IMAGE_SIZE / 2,
                            game->snake[i].y * IMAGE_SIZE + IMAGE_SIZE / 2);
    }

    // Draw food
    rect.x = game->food_x * IMAGE_SIZE;
    rect.y = game->food_y * IMAGE_SIZE;
    rect.w = IMAGE_SIZE;
    rect.h = IMAGE_SIZE;
    SDL_RenderCopy(game->renderer, game->food_texture, NULL, &rect);

    // Draw score
    char score_text[64];
    sprintf(score_text, "Score: %d", game->score);
    SDL_SetRenderDrawColor(game->renderer, 0xFF, 0xFF, 0xFF, SDL_ALPHA_OPAQUE);
    SDL_RenderDrawFilledRect(game->renderer, 10, 10, 80, 20);
    SDL_SetRenderDrawColor(game->renderer, 0x00, 0x00, 0x00, SDL_ALPHA_OPAQUE);
    SDL_RenderDrawRect(game->renderer, 9, 9, 81, 21);
    SDL_SetTextureColorMod(game->renderer, 255, 255, 255);
    SDL_RenderText(game->renderer, score_text, 20, 20);

    // Update the screen
    SDL_RenderPresent(game->renderer);
}

void HandleInput(Game *game) {
    SDL_Event event;

    while (SDL_PollEvent(&event)) {
        if (event.type == SDL_KEYDOWN) {
            switch (event.key.keysym.sym) {
                case SDLK_UP:
                    game->snake[0].direction = SDL_SCANCODE_UP;
                    break;
                case SDLK_DOWN:
                    game->snake[0].direction = SDL_SCANCODE_DOWN;
                    break;
                case SDLK_LEFT:
                    game->snake[0].direction = SDL_SCANCODE_LEFT;
                    break;
                case SDLK_RIGHT:
                    game->snake[0].direction = SDL_SCANCODE_RIGHT;
                    break;
                case SDLK_p:
                    game->frame_rate += 10;
                    break;
                case SDLK_m:
                    game->frame_rate -= 10;
                    break;
            }
        } else if (event.type == SDL_QUIT) {
            game->game_state = GameStateGameOver;
        }
    }
}

void FreeGame(Game *game) {
    SDL_DestroyTexture(game->background_texture);
    SDL_FreeSurface(game->snake_head_surface);
    SDL_FreeSurface(game->snake_body_surface);
    SDL_FreeSurface(game->food_surface);
    SDL_DestroyRenderer(game->renderer);
    SDL_DestroyWindow(game->window);
    SDL_Quit();
}

bool CheckCollision(SnakeSegment *snake, int snake_length, int x, int y) {
    for (int I = 0; I < snake_length; ++i) {
        if (snake[i].x == x && snake[i].y == y) {
            return true;
        }
    }
    return false;
}
